mapper.update:
UPDATE video_status_flush_batch
SET cleanup_retry_count = cleanup_retry_count + 1,
    last_attempt_at = NOW(3),
    last_error = #{lastError}
WHERE batch_id = #{batchId}
  AND cleanup_status = 0

UPDATE video_status_flush_batch
SET cleanup_status = 3,
    last_attempt_at = NOW(3),
    last_error = #{lastError}
WHERE batch_id = #{batchId}
  AND cleanup_status = 0
